import akka.actor.typed.ActorRef; import akka.actor.typed.Behavior; import akka.actor.typed.SupervisorStrategy; import akka.actor.typed.javadsl.ActorContext; import akka.actor.typed.javadsl.Behaviors; public class SupervisorActor { public interface Command {} public record Process( int number, ActorRef<Result> replyTo ) implements Command {} public record Result( String worker, int number, int result ) {} public static Behavior<Command> create() { return Behaviors.setup(context -> { ActorRef<WorkerActor.Command> worker1 = context.spawn( Behaviors.supervise( WorkerActor.create("Worker-1") ).onFailure( RuntimeException.class, SupervisorStrategy.restart() ), "worker1" ); ActorRef<WorkerActor.Command> worker2 = context.spawn( Behaviors.supervise( WorkerActor.create("Worker-2") ).onFailure( RuntimeException.class, SupervisorStrategy.restart() ), "worker2" ); ActorRef<WorkerActor.Command> worker3 = context.spawn( Behaviors.supervise( WorkerActor.create("Worker-3") ).onFailure( RuntimeException.class, SupervisorStrategy.restart() ), "worker3" ); ActorRef<?>[] workers = { worker1, worker2, worker3 }; return Behaviors.receive(Command.class) .onMessage(Process.class, message -> { int index = Math.abs(message.number()) % workers.length; @SuppressWarnings("unchecked") ActorRef<WorkerActor.Command> worker = (ActorRef<WorkerActor.Command>) workers[index]; context.getLog().info( "Supervisor enviando tarea al worker {}", index + 1 ); worker.tell( new WorkerActor.Process( message.number(), message.replyTo() ) ); return Behaviors.same(); }) .build(); }); } }
